using Microsoft.AspNetCore.Http.Features;

namespace Legacy.Maliev.Web.Components.Layout;

/// <summary>
/// Carries the public cookie banner decision and consent cookie generated by the request feature.
/// </summary>
/// <param name="ShowBanner">Whether tracking is unavailable and the visitor has not already recorded a denial.</param>
/// <param name="ConsentCookie">The consent cookie produced by the tracking feature, or null when the feature is absent.</param>
public sealed record PublicCookieConsentDisplayModel(bool ShowBanner, string? ConsentCookie)
{
    private const string TrackingConsentCookieName = "maliev_tracking_consent";

    /// <summary>
    /// Resolves cookie-banner visibility without prompting again after a recorded denial.
    /// </summary>
    /// <param name="context">The current request containing consent features and cookies.</param>
    /// <returns>The banner decision and available consent cookie.</returns>
    public static PublicCookieConsentDisplayModel Create(HttpContext context)
    {
        ArgumentNullException.ThrowIfNull(context);

        var consentFeature = context.Features.Get<ITrackingConsentFeature>();
        var hasRecordedDenial = string.Equals(
            context.Request.Cookies[TrackingConsentCookieName],
            "denied",
            StringComparison.Ordinal);

        return new PublicCookieConsentDisplayModel(
            consentFeature?.CanTrack != true && !hasRecordedDenial,
            consentFeature?.CreateConsentCookie());
    }
}
